'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Waveform } from '@phosphor-icons/react';
import { NAV_ITEMS, SITE } from '@/lib/site';
import type { Dictionary, Locale } from '@/lib/i18n';
import LanguageSwitcher from './LanguageSwitcher';

export default function SiteNav({
  locale,
  dictionary,
}: {
  locale: Locale;
  dictionary: Dictionary;
}) {
  const pathname = usePathname();
  const nav = dictionary.nav;

  return (
    <header className="sticky top-0 z-50 border-b border-white/10 bg-bg/70 backdrop-blur-md">
      <nav className="mx-auto flex h-[68px] w-full max-w-6xl items-center justify-between px-6">
        <Link href="/" className="flex items-center gap-2 font-bold" aria-label={`${SITE.name} home`}>
          <span className="grid h-8 w-8 place-items-center rounded-lg bg-accent text-on-accent">
            <Waveform size={20} weight="bold" aria-hidden />
          </span>
          <span className="text-lg">{SITE.name}</span>
        </Link>

        <ul className="flex items-center gap-7">
          {NAV_ITEMS.map((item) => {
            const active = pathname === item.href || pathname.startsWith(item.href + '/');
            return (
              <li key={item.href}>
                <Link
                  href={item.href}
                  className={`text-sm font-medium transition ${
                    active ? 'text-text' : 'text-muted hover:text-text'
                  }`}
                >
                  {nav[item.key]}
                </Link>
              </li>
            );
          })}
        </ul>

        <div className="flex items-center gap-3">
          <LanguageSwitcher locale={locale} labels={dictionary} />
        </div>
      </nav>
    </header>
  );
}
